export const zConfigKind = z.enum(['CHANNEL_THRESHOLDS', 'MCC_CIRCUIT_BREAKER']);

/**
 * PENDING_APPROVAL (loosening, not applied), APPLIED_PENDING_CONFIRMATION (tightening, in effect until confirmed or reverted), APPROVED (loosening applied), CONFIRMED (tightening kept), REJECTED (loosening never applied), REVERTED (tightening undone by rejection or by the 24-hour deadline), SUPERSEDED (replaced by a later tightening before review), WITHDRAWN (loosening withdrawn by its proposer).
 */
export const zConfigChangeStatus = z.enum([
    'PENDING_APPROVAL',
    'APPLIED_PENDING_CONFIRMATION',
    'APPROVED',
    'CONFIRMED',
    'REJECTED',
    'REVERTED',
    'SUPERSEDED',
    'WITHDRAWN'
]);

